//! Cargo-driven `wdmaud.drv` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is wdmaud_drv-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x6d0c0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fe53000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fe53000000u64)),
        o => panic!("wdmaud_drv-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:c:libsamplerate", "engine:crate:mmixer-rust:user:FALSE", "import:user32", "import:winmm", "import:advapi32", "import:msvcrt", "import:setupapi", "import:ksuser", "import:kernel32", "import:ntdll", "engine:crate:mmebuddy-rust::TRUE", "engine:oldnames"],
        "x86_64" => &["body", "engine:c:libsamplerate", "engine:crate:mmixer-rust:user:FALSE", "import:user32", "import:winmm", "import:advapi32", "import:msvcrt", "import:setupapi", "import:ksuser", "import:kernel32", "import:ntdll", "engine:crate:mmebuddy-rust::TRUE", "engine:oldnames"],
        "aarch64" => &["body", "engine:c:libsamplerate", "engine:crate:mmixer-rust:user:FALSE", "import:user32", "import:winmm", "import:advapi32", "import:msvcrt", "import:setupapi", "import:ksuser", "import:kernel32", "import:ntdll", "engine:crate:mmebuddy-rust::TRUE", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/wdmaud.drv",
        "dll/win32/wdmaud.drv",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/include/reactos/libs/sound",
        "drivers/wdm/audio/legacy/wdmaud",
        "sdk/lib/drivers/sound/mmixer",
        "vendor/libsamplerate",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=+sse,+sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("wdmaud_drv-rust")
        .rc("dll/win32/wdmaud.drv/wdmaud.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/wdmaud.drv/wdmaud.spec", "wdmaud.drv")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/winmm/winmm.spec", "winmm.dll", "winmm")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/setupapi/setupapi.spec", "setupapi.dll", "setupapi")
        .import_lib("dll/directx/ksuser/ksuser.spec", "ksuser.dll", "ksuser")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
